const RACER_STYLE='fulmine',AI_COUNT=3,TURBO_CHARGES=3,TURBO_SECONDS=2.6,WIN_REWARD=350,LOSE_PENALTY=100,TRACK_LIMIT=82,SAMPLE_SPACING=28,RACE_LABEL='GARA IN TANGENZIALE';
const START_GRID=[{side:-1.45,back:0},{side:1.45,back:0},{side:-1.45,back:6.5},{side:1.45,back:6.5}];
const managers=new WeakMap();let activeManager=null;const materialCache=new Map();
function material(color,basic=false){const key=(basic?'b:':'s:')+color;if(!materialCache.has(key))materialCache.set(key,basic?new THREE.MeshBasicMaterial({color}):new THREE.MeshStandardMaterial({color,roughness:.62}));return materialCache.get(key);}
function box(root,color,x,y,z,w,h,d,basic=false){const mesh=new THREE.Mesh(new THREE.BoxGeometry(w,h,d),material(color,basic));mesh.position.set(x,y,z);mesh.castShadow=!basic;mesh.receiveShadow=!basic;root.add(mesh);return mesh;}
function sphere(root,color,x,y,z,r,basic=false){const mesh=new THREE.Mesh(new THREE.SphereGeometry(r,10,8),material(color,basic));mesh.position.set(x,y,z);root.add(mesh);return mesh;}
function yawAt(path,i){const a=path[Math.max(0,i-1)],b=path[Math.min(path.length-1,i+1)];return Math.atan2(b.x-a.x,b.z-a.z);}
function angleDelta(a,b){return Math.abs(Math.atan2(Math.sin(a-b),Math.cos(a-b)));}
function lateral(p,yaw,offset){return {x:p.x+Math.cos(yaw)*offset,z:p.z-Math.sin(yaw)*offset};}
function saveMoney(state){try{const old=JSON.parse(localStorage.getItem('padova-game-v1')||'{}');old.money=state.money;old.jobs=state.jobs;old.quality=state.quality;old.character=state.character;localStorage.setItem('padova-game-v1',JSON.stringify(old));}catch{}}
function trackHeight(game,p,x=p.x,z=p.z,referenceY=null){const y=p?.road?game.terrain.roads?.sample?.(p.road,x,z):NaN;return Number.isFinite(y)?y+.05:game.terrain.height(x,z,referenceY);}
function sampleDistance(actor,p){const flat=dist(actor,p);if(!Number.isFinite(actor.y)||!Number.isFinite(p.y))return flat;return Math.hypot(flat,(actor.y-p.y)*4);}
function samplePolyline(path,spacing=SAMPLE_SPACING){if(path.length<2)return path.map(p=>({...p}));const out=[{...path[0]}],cum=[0];let carry=0,total=0;for(let i=1;i<path.length;i++){let a={...path[i-1]},b=path[i],seg=dist(a,b);while(carry+seg>=spacing){const need=spacing-carry,t=need/Math.max(seg,.001),p={x:a.x+(b.x-a.x)*t,z:a.z+(b.z-a.z)*t,road:b.road||a.road};total+=spacing;out.push(p);cum.push(total);a=p;seg=dist(a,b);carry=0;}carry+=seg;}const last=path.at(-1);if(dist(out.at(-1),last)>3){total+=dist(out.at(-1),last);out.push({...last});cum.push(total);}return Object.assign(out,{cumulative:cum,total});}
function prepareSamples(game,path){const samples=samplePolyline(path);for(const p of samples)p.y=trackHeight(game,p);return samples;}
function offsetPath(path,offset){return path.map((p,i)=>({...p,...lateral(p,yawAt(path,i),offset)}));}
function motorwaySegments(graph,links=false){const re=links?/^(motorway|trunk)(?:_link)?$/:/^(motorway|trunk)$/;return graph.segments.filter(s=>s.connected&&re.test(s.road.k)&&s.road.w>=7&&!['no','private'].includes(s.road.access));}
function largestComponent(graph,segments){const adj=new Map(),add=(a,b,w)=>{if(!adj.has(a))adj.set(a,[]);adj.get(a).push({id:b,w});};for(const s of segments){const a=graph.nodes[s.a],b=graph.nodes[s.b],w=dist(a,b);add(s.a,s.b,w);add(s.b,s.a,w);}let best=[];const seen=new Set();for(const start of adj.keys()){if(seen.has(start))continue;const q=[start],part=[];seen.add(start);for(let i=0;i<q.length;i++){const n=q[i];part.push(n);for(const e of adj.get(n)||[])if(!seen.has(e.id)){seen.add(e.id);q.push(e.id);}}if(part.length>best.length)best=part;}return {nodes:new Set(best)};}
function farthestPath(graph,component,segments){const allowed=component.nodes,roadKeys=new Set(segments.map(s=>s.road)),directed=new Map();for(const id of allowed)for(const e of graph.nodes[id].edges||[]){if(!allowed.has(e.id)||!roadKeys.has(e.road))continue;if(!directed.has(id))directed.set(id,[]);directed.get(id).push({id:e.id,w:e.d,road:e.road});}const ids=[...allowed];if(ids.length<2)return null;const extremes=[...new Set([ids.reduce((a,b)=>graph.nodes[a].x<graph.nodes[b].x?a:b),ids.reduce((a,b)=>graph.nodes[a].x>graph.nodes[b].x?a:b),ids.reduce((a,b)=>graph.nodes[a].z<graph.nodes[b].z?a:b),ids.reduce((a,b)=>graph.nodes[a].z>graph.nodes[b].z?a:b)])];let best=null;for(const start of extremes){const d=new Map([[start,0]]),prev=new Map(),used=new Set();while(true){let u=null,du=Infinity;for(const [id,val] of d)if(!used.has(id)&&val<du){u=id;du=val;}if(u===null)break;used.add(u);for(const e of directed.get(u)||[]){const nd=du+e.w;if(nd<(d.get(e.id)??Infinity)){d.set(e.id,nd);prev.set(e.id,{id:u,road:e.road});}}}let far=start,farD=0;for(const [id,val] of d)if(val>farD){far=id;farD=val;}if(!best||farD>best.length){const nodes=[far],roads=[];let cursor=far;while(cursor!==start&&prev.has(cursor)){const step=prev.get(cursor);roads.unshift(step.road);nodes.unshift(step.id);cursor=step.id;}if(nodes[0]===start){const path=nodes.map((id,i)=>({x:graph.nodes[id].x,z:graph.nodes[id].z,road:i===0?roads[0]:roads[i-1]||roads.at(-1)}));best={length:farD,path};}}}return best;}
function chooseRaceRoute(game){for(const links of [false,true]){const segments=motorwaySegments(game.graph,links);if(!segments.length)continue;const candidate=farthestPath(game.graph,largestComponent(game.graph,segments),segments);if(candidate?.length>1800)return candidate.path;}return null;}
function chooseStartIndex(game,samples){const end=Math.min(samples.length-8,Math.max(8,Math.floor(samples.length*.28)));let best=null;for(let i=4;i<=end;i++){const p=samples[i],road=p.road;if(!road||road.tunnel||road.b||road.crossing||Number(road.layer)>0||road.w<7)continue;const bend=angleDelta(yawAt(samples,i-2),yawAt(samples,i+2)),grade=Math.abs((samples[i+2]?.y??p.y)-(samples[i-2]?.y??p.y))/(SAMPLE_SPACING*4),score=bend*9+grade*24-road.w*.025;if(!best||score<best.score)best={index:i,score};}return best?.index??Math.min(4,samples.length-2);}
function progressAt(r,index){return Math.max(0,(r.samples.cumulative[index]||0)-r.startDistance);}
function nearestSample(actor,samples,hint=0){let best=clamp(hint,0,samples.length-1),bestD=Infinity;const lo=Math.max(0,best-12),hi=Math.min(samples.length-1,best+20);for(let i=lo;i<=hi;i++){const d=sampleDistance(actor,samples[i]);if(d<bestD){bestD=d;best=i;}}if(bestD>TRACK_LIMIT)for(let i=0;i<samples.length;i+=3){const d=sampleDistance(actor,samples[i]);if(d<bestD){bestD=d;best=i;}}return {index:best,d:bestD};}
function routeWithDetours(samples,baseOffset,obstacles){const line=offsetPath(samples,baseOffset);for(const o of obstacles){const target=o.side>0?-1.35:1.35;for(let k=-3;k<=3;k++){const i=o.index+k;if(i<1||i>=line.length-1)continue;const blend=1-Math.abs(k)/4,shift=baseOffset+(target-baseOffset)*blend;Object.assign(line[i],lateral(samples[i],yawAt(samples,i),shift));}}return line;}
function addLivery(car,index){const colors=[['#ff3cac','#2bd9fe'],['#d8ff3e','#6f2cff'],['#ff8a32','#18e0c2'],['#f1f1f1','#e92762']][index%4],root=new THREE.Group();root.name='tangenziale-livery';for(const [j,c] of colors.entries()){const stripe=box(root,c,(j?1:-1)*.24,1.12,-.08,.18,.025,2.45,true);stripe.rotation.y=(j?1:-1)*.08;}box(root,colors[1],0,1.29,-1.72,1.65,.055,.24,true);car.mesh.add(root);}
function buildStartSet(game,start,yaw){const root=new THREE.Group();root.name='tangenziale-start-set';root.position.set(start.x,trackHeight(game,start),start.z);root.rotation.y=yaw;for(const side of [-1,1]){const x=side*7.2;for(const sx of [-1.8,1.8])for(const sz of [-1.5,1.5])box(root,'#e8e2d6',x+sx,1.15,sz,.1,2.3,.1);const roof=box(root,side<0?'#c93752':'#2e7587',x,2.42,0,4.1,.18,3.6);roof.rotation.z=side*.04;}for(const side of [-1,1])box(root,'#d9d7ce',side*5.2,2.5,.15,.18,5,.18);box(root,'#242b31',0,4.85,.15,10.5,.34,.28);const lights=[];for(const x of [-1.8,-.6,.6,1.8]){const housing=sphere(root,'#271c1d',x,4.72,.36,.31,true),lamp=sphere(root,'#3b171b',x,4.72,.50,.22,true);housing.scale.z=.55;lights.push(lamp);}const marshal=new THREE.Group();marshal.name='flag-marshal';marshal.position.set(-6,0,1.4);box(marshal,'#1d2730',0,.62,0,.42,.82,.28);box(marshal,'#d74b62',0,1.28,0,.5,.55,.3);sphere(marshal,'#ead7c3',0,1.72,0,.22);box(marshal,'#43342f',0,1.83,-.04,.47,.18,.28);const pole=box(marshal,'#d8d8cf',.42,1.42,0,.035,2.1,.035);pole.rotation.z=-.12;const flag=box(marshal,'#f1efe7',.83,2.04,0,.78,.5,.035,true);flag.userData.flag=true;marshal.add(flag);root.add(marshal);game.scene.add(root);return {root,lights,flag};}
function buildFinishSet(game,finish,yaw){const root=new THREE.Group();root.name='tangenziale-finish-set';root.position.set(finish.x,trackHeight(game,finish),finish.z);root.rotation.y=yaw;for(const side of [-1,1])box(root,'#e7e5dc',side*5.1,2.3,0,.18,4.6,.18);box(root,'#1f252b',0,4.4,0,10.3,.5,.25);for(let i=-5;i<=5;i++)box(root,i%2?'#f2f0e6':'#20262c',i*.9,4.4,.14,.9,.43,.035,true);game.scene.add(root);return root;}
function buildRamp(game,samples,index,side){const p=samples[index],yaw=yawAt(samples,index),q=lateral(p,yaw,side*1.7),width=4.6,length=11,rise=1.35,y=trackHeight(game,p,q.x,q.z,p.y);return {kind:'tangenziale-race-ramp',tangenzialeRace:true,x:q.x,z:q.z,yaw,width,length,rise,topY:[y+.05,y+.05,y+rise,y+rise]};}
function addRampVisual(root,r){const mesh=box(root,'#c28a35',r.x,(r.topY[0]+r.topY[2])*.5-.04,r.z,r.width,.18,r.length);mesh.rotation.order='YXZ';mesh.rotation.y=r.yaw;mesh.rotation.x=-Math.atan2(r.rise,r.length);}
function gridPose(game,race,cfg){const base={x:race.start.x-Math.sin(race.startYaw)*cfg.back,z:race.start.z-Math.cos(race.startYaw)*cfg.back},p=lateral(base,race.startYaw,cfg.side);return {...p,y:trackHeight(game,race.start,p.x,p.z,race.start.y)};}

export class TangenzialeRace{
 constructor(game){this.game=game;this.race=null;this.routeCache=null;this.keyDown=this.keyDown.bind(this);this.keyUp=this.keyUp.bind(this);window.addEventListener('keydown',this.keyDown,true);window.addEventListener('keyup',this.keyUp,true);}
 keyDown(e){const r=this.race;if(!r)return;if(['KeyE','KeyJ','KeyV','KeyM'].includes(e.code)){e.preventDefault();e.stopImmediatePropagation();if(e.code==='KeyE')this.game.toast('Non puoi scendere dall’auto durante la gara.',1.5);return;}if(!['ShiftLeft','ShiftRight'].includes(e.code))return;e.preventDefault();e.stopImmediatePropagation();if(e.repeat||r.phase!=='running'||r.playerTurboUntil>this.game.state.elapsed)return;if(r.playerTurbo<=0){this.game.toast('Turbo esauriti · continua senza boost.',1.5);return;}r.playerTurbo--;r.playerTurboUntil=this.game.state.elapsed+TURBO_SECONDS;this.game.toast('TURBO · '+r.playerTurbo+' rimasti',1.5);}
 keyUp(e){if(!this.race||!['ShiftLeft','ShiftRight'].includes(e.code))return;e.preventDefault();e.stopImmediatePropagation();}
 openConfirmation(){const game=this.game;if(this.race)return;if(game.state.mission){game.toast('Concludi o annulla la missione attiva prima della gara.',4);document.getElementById('menu')?.close();game.state.paused=false;return;}const menu=document.getElementById('menu'),title=document.getElementById('menuTitle'),content=document.getElementById('menuContent');if(!menu||!content)return;if(title)title.textContent='Gara in tangenziale';content.innerHTML='<p class="about-copy"><strong>Sei sicuro di voler iniziare?</strong><br>Verrai teletrasportato automaticamente sulla tangenziale. 4 Fulmine R identiche, 3 turbo su <kbd>SHIFT</kbd>, rampe e traffico da schivare.<br><strong>Vittoria +€350 · sconfitta -€100.</strong></p><div class="menu-actions"><button class="primary" id="startTangenzialeRace">INIZIA GARA</button><button id="cancelTangenzialeRace">ANNULLA</button></div>';document.getElementById('startTangenzialeRace').onclick=()=>this.start();document.getElementById('cancelTangenzialeRace').onclick=()=>{menu.close();game.state.paused=false;};}
 snapshot(){const s=this.game.state,c=s.car;return {mode:s.mode,x:s.x,z:s.z,y:s.y,yaw:s.yaw,speed:s.speed,vy:s.vy,health:s.health,wanted:s.wanted,escape:s.escape,busted:s.busted,car:c,waypoint:s.waypoint,route:Array.isArray(s.route)?s.route.map(p=>({...p})):[],carPose:c?{x:c.x,z:c.z,y:c.y,yaw:c.yaw,speed:c.speed,health:c.health,parked:c.parked,visible:c.mesh.visible}:null,gameGraceUntil:this.game.graceUntil};}
 start(){const game=this.game,s=game.state,raw=this.routeCache||chooseRaceRoute(game);if(!raw){game.toast('Tangenziale non disponibile in questa versione della rete stradale.',5);return;}this.routeCache=raw;const samples=prepareSamples(game,raw);if(samples.length<70||samples.total<1800){game.toast('Tratto di tangenziale troppo corto per avviare la gara.',5);return;}document.getElementById('menu')?.close();s.paused=false;const snapshot=this.snapshot();if(snapshot.car){snapshot.car.parked=true;snapshot.car.speed=0;game.pose(snapshot.car);}const startIndex=chooseStartIndex(game,samples),start=samples[startIndex],startYaw=yawAt(samples,startIndex),finish=samples.at(-2),finishYaw=yawAt(samples,samples.length-2),startDistance=samples.cumulative[startIndex]||0,total=Math.max(1,samples.total-startDistance),race={phase:'countdown',startedAt:s.elapsed,countdownAt:s.elapsed,snapshot,samples,total,startDistance,startIndex,start,startYaw,finish,finishYaw,playerCar:null,ai:[],obstacles:[],roots:[],ramps:[],playerTurbo:TURBO_CHARGES,playerTurboUntil:0,playerHint:startIndex,playerProgress:0,lastSafe:startIndex,finished:false};const obstacleDefs=[{index:Math.floor(startIndex+(samples.length-startIndex)*.34),side:1},{index:Math.floor(startIndex+(samples.length-startIndex)*.61),side:-1},{index:Math.floor(startIndex+(samples.length-startIndex)*.84),side:1}].filter(o=>o.index>startIndex+8&&o.index<samples.length-8);race.obstacleDefs=obstacleDefs;const cars=[];for(let i=0;i<AI_COUNT+1;i++){const p=gridPose(game,race,START_GRID[i]),c=game.addCar(p.x,p.z,startYaw,false,true,RACER_STYLE);Object.assign(c,{x:p.x,z:p.z,y:p.y,yaw:startYaw,speed:0,health:100,parked:true,missionUnit:true,fixedSpawn:true,tangenzialeRace:true});addLivery(c,i);game.pose(c);cars.push(c);}race.playerCar=cars[0];game.claim(race.playerCar);race.playerCar.missionUnit=true;race.playerCar.fixedSpawn=true;race.playerCar.tangenzialeRace=true;const skills=[.965,.99,1.01],offsets=[1.25,-1.2,.15];for(let i=0;i<AI_COUNT;i++){const c=cars[i+1],line=routeWithDetours(samples,offsets[i],obstacleDefs);Object.assign(c,{parked:false,path:line,pathIndex:startIndex+1,stuck:0,raceSkill:skills[i],raceTurbo:TURBO_CHARGES,raceTurboIndex:0,raceTurboUntil:0,raceHint:startIndex,raceProgress:0});race.ai.push(c);}for(const [i,o] of obstacleDefs.entries()){const p=samples[o.index],yaw=yawAt(samples,o.index),q=lateral(p,yaw,o.side*1.9),style=['wagon','utility','sedan'][i%3],c=game.addCar(q.x,q.z,yaw,false,true,style);Object.assign(c,{x:q.x,z:q.z,y:trackHeight(game,p,q.x,q.z,p.y),yaw,speed:0,parked:true,missionUnit:true,fixedSpawn:true,tangenzialeObstacle:true});game.pose(c);race.obstacles.push(c);}const rampRoot=new THREE.Group();rampRoot.name='tangenziale-race-ramps';for(const [idx,side] of [[.25,-1],[.50,1],[.74,-1]]){const index=Math.floor(startIndex+(samples.length-startIndex)*idx),r=buildRamp(game,samples,index,side);race.ramps.push(r);addRampVisual(rampRoot,r);}game.terrain.arcadeRamps=[...(game.terrain.arcadeRamps||[]),...race.ramps];game.scene.add(rampRoot);race.roots.push(rampRoot);race.startSet=buildStartSet(game,start,startYaw);race.finishSet=buildFinishSet(game,finish,finishYaw);race.roots.push(race.startSet.root,race.finishSet);Object.assign(s,{mode:'car',car:race.playerCar,x:race.playerCar.x,z:race.playerCar.z,y:race.playerCar.y,yaw:startYaw,speed:0,vy:0,health:100,wanted:0,escape:0,busted:0,waypoint:{x:finish.x,z:finish.z,name:'TRAGUARDO · Tangenziale'},route:samples.slice(startIndex).map(p=>({x:p.x,z:p.z}))});resetGroundMotion(race.playerCar);this.race=race;activeManager=this;game.graceUntil=Infinity;game.toast('GARA TANGENZIALE · quattro semafori rossi, poi VIA.',4);}
 freezeGrid(){const r=this.race,s=this.game.state,c=r.playerCar,all=[c,...r.ai];for(let i=0;i<all.length;i++){const a=all[i],p=gridPose(this.game,r,START_GRID[i]);Object.assign(a,{x:p.x,z:p.z,y:p.y,yaw:r.startYaw,speed:0,health:100});resetGroundMotion(a);this.game.pose(a);}Object.assign(s,{x:c.x,z:c.z,y:c.y,yaw:c.yaw,speed:0,vy:0,health:100});}
 countdown(){const r=this.race,t=this.game.state.elapsed-r.countdownAt;this.freezeGrid();const on=Math.min(4,Math.floor(t/.55)+1);for(let i=0;i<r.startSet.lights.length;i++)r.startSet.lights[i].material=material(i<on?'#ff263d':'#3b171b',true);if(r.startSet.flag)r.startSet.flag.rotation.z=Math.sin(t*2)*.05;if(t>=3.05){for(const lamp of r.startSet.lights)lamp.material=material('#151719',true);r.phase='running';r.startedAt=this.game.state.elapsed;for(const c of r.ai)c.parked=false;r.playerCar.parked=false;this.game.toast('VIA! · SHIFT = turbo · 3 cariche',3);}}
 applyPlayerTurbo(dt){const r=this.race,s=this.game.state;if(s.elapsed>=r.playerTurboUntil)return;const cap=r.playerCar.spec.max*1.11;s.speed=Math.min(cap,s.speed+8.5*dt);r.playerCar.speed=s.speed;}
 updateAI(dt){const r=this.race,traffic=[r.playerCar,...r.ai,...r.obstacles];for(const [i,c] of r.ai.entries()){if(!c.mesh.visible||c.health<=0){this.respawnActor(c,c.raceHint||r.startIndex,[-1.2,0,1.2][i]);c.health=100;c.mesh.visible=true;}const p=nearestSample(c,r.samples,c.raceHint||r.startIndex);c.raceHint=p.index;c.raceProgress=Math.max(c.raceProgress||0,progressAt(r,p.index));const frac=c.raceProgress/r.total,plans=[[.17,.48,.78],[.22,.53,.81],[.14,.44,.73]][i];if(c.raceTurbo>0&&c.raceTurboIndex<plans.length&&frac>=plans[c.raceTurboIndex]){c.raceTurbo--;c.raceTurboIndex++;c.raceTurboUntil=this.game.state.elapsed+TURBO_SECONDS;}const boost=this.game.state.elapsed<c.raceTurboUntil,max=c.spec.max*c.raceSkill+(boost?6.2:0);followRoad(c,dt,this.game.graph,this.game.terrain,this.game.collision,{max,accel:14.5+i*.25,turnRate:1.75,traffic:traffic.filter(o=>o!==c)});this.game.pose(c);if(p.d>TRACK_LIMIT||c.stuck>4.3)this.respawnActor(c,Math.max(r.startIndex,p.index-3),[-1.2,0,1.2][i]);}}
 respawnActor(car,index,offset=0){const r=this.race,i=clamp(index,r.startIndex,r.samples.length-2),p=r.samples[i],yaw=yawAt(r.samples,i),q=lateral(p,yaw,offset),y=trackHeight(this.game,p,q.x,q.z,p.y);Object.assign(car,{x:q.x,z:q.z,y,yaw,speed:0,health:100,stuck:0});resetGroundMotion(car);this.game.pose(car);if(car===r.playerCar)Object.assign(this.game.state,{x:car.x,z:car.z,y:car.y,yaw:car.yaw,speed:0,vy:0,health:100});}
 updatePlayer(){const r=this.race,s=this.game.state;if(s.car!==r.playerCar||s.mode!=='car'||s.health<=0){this.finish(false,'Veicolo fuori gara');return false;}const p=nearestSample(s,r.samples,r.playerHint);r.playerHint=p.index;r.playerProgress=Math.max(r.playerProgress,progressAt(r,p.index));if(p.index>r.lastSafe)r.lastSafe=p.index;if(p.d>TRACK_LIMIT||s.x<-5970||s.x>7250||s.z<-6480||s.z>6230){this.respawnActor(r.playerCar,Math.max(r.startIndex,r.lastSafe-2),-1);this.game.toast('Fuori tracciato · respawn sulla tangenziale.',2.5);}return true;}
 rank(){const r=this.race,values=[{player:true,p:r.playerProgress},...r.ai.map(c=>({player:false,p:c.raceProgress||0}))].sort((a,b)=>b.p-a.p);return values.findIndex(v=>v.player)+1;}
 paintHud(){const r=this.race;if(!r)return;queueMicrotask(()=>{if(!this.race)return;const type=document.getElementById('missionType'),title=document.getElementById('missionTitle'),desc=document.getElementById('missionDesc'),timer=document.getElementById('missionTimer');if(type)type.textContent='GARA TANGENZIALE';if(title)title.textContent=r.phase==='countdown'?'GRIGLIA DI PARTENZA':'Posizione '+this.rank()+' / 4';if(desc)desc.textContent='Fulmine R · Turbo '+r.playerTurbo+'/3 · SHIFT · '+Math.round(Math.min(100,r.playerProgress/r.total*100))+'% percorso';if(timer)timer.textContent=r.phase==='countdown'?'ROSSI':Math.max(0,(r.total-r.playerProgress)/1000).toFixed(1)+' KM';});}
 finish(win,reason=''){const r=this.race;if(!r||r.finished)return;r.finished=true;const game=this.game,s=game.state;s.money+=win?WIN_REWARD:-LOSE_PENALTY;saveMoney(s);const money=s.money;this.restoreSnapshot();s.money=money;saveMoney(s);game.toast(win?'VITTORIA · +€350':('SCONFITTA · -€100'+(reason?' · '+reason:'')),6);}
 restoreSnapshot(){const r=this.race;if(!r)return;const game=this.game,s=game.state,snap=r.snapshot;game.terrain.arcadeRamps=(game.terrain.arcadeRamps||[]).filter(x=>!x.tangenzialeRace);for(const root of r.roots)game.scene.remove(root);for(const c of [...r.ai,r.playerCar,...r.obstacles]){if(!c||c===snap.car)continue;try{game.retire(c);}catch{game.remove(c);}}this.race=null;game.graceUntil=snap.gameGraceUntil;const c=snap.car;if(c&&snap.carPose){Object.assign(c,snap.carPose);c.mesh.visible=snap.carPose.visible;resetGroundMotion(c);game.pose(c);}Object.assign(s,{mode:snap.mode,x:snap.x,z:snap.z,y:snap.y,yaw:snap.yaw,speed:snap.speed,vy:snap.vy,health:snap.health,wanted:snap.wanted,escape:snap.escape,busted:snap.busted,car:c||null,waypoint:snap.waypoint,route:snap.route});activeManager=this;}
 update(dt){activeManager=this;const r=this.race;if(!r)return;if(r.phase==='countdown'){this.countdown();this.paintHud();return;}if(r.phase!=='running')return;this.applyPlayerTurbo(dt);this.updateAI(dt);if(!this.updatePlayer())return;this.game.state.wanted=0;this.game.state.escape=0;const playerDone=r.playerProgress>=r.total-35||dist(this.game.state,r.finish)<22,aiDone=r.ai.some(c=>(c.raceProgress||0)>=r.total-35||dist(c,r.finish)<22);if(playerDone){this.finish(true);return;}if(aiDone){this.finish(false,'un avversario ha tagliato il traguardo per primo');return;}this.paintHud();}
}
function decorateActivities(){const content=document.getElementById('menuContent'),title=document.getElementById('menuTitle');if(!content||!/A little extra on the side\./i.test(title?.textContent||''))return;const list=content.querySelector('.activities');if(!list||document.getElementById('tangenzialeRaceActivity'))return;const b=document.createElement('button');b.id='tangenzialeRaceActivity';b.className='activity';b.innerHTML='<span class="icon">⚑</span><span><b>'+RACE_LABEL+'</b><small>4 Fulmine R · 3 turbo SHIFT · rampe · ostacoli</small></span><span class="reward">+€350</span>';b.onclick=()=>activeManager?.openConfirmation();list.appendChild(b);}
new MutationObserver(decorateActivities).observe(document.getElementById('menuContent')||document.body,{childList:true,subtree:true});
const originalUpdate=ModernGameplay.prototype.update;
if(!ModernGameplay.prototype.__tangenzialeRace){ModernGameplay.prototype.__tangenzialeRace=true;ModernGameplay.prototype.update=function(dt){originalUpdate.call(this,dt);let m=managers.get(this);if(!m){m=new TangenzialeRace(this);managers.set(this,m);}m.update(dt);};}
